import{_ as a,o,c as r,ag as t}from"./chunks/framework.BSsJcWLc.js";const u=JSON.parse('{"title":"Machine Learning Layer","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/ml-layer.md","filePath":"architecture/ml-layer.md"}'),i={name:"architecture/ml-layer.md"};function n(d,e,c,s,l,p){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="machine-learning-layer" tabindex="-1">Machine Learning Layer <a class="header-anchor" href="#machine-learning-layer" aria-label="Permalink to &quot;Machine Learning Layer&quot;">​</a></h1><p>Decoder pipelines with sklearn-compatible <code>fit</code>/<code>predict</code> interface for cross-validation and real-time inference. All pipelines accept <code>(n_samples, n_channels, n_times)</code> and return class indices + softmax confidence arrays.</p><hr><h2 id="decoders" tabindex="-1">Decoders <a class="header-anchor" href="#decoders" aria-label="Permalink to &quot;Decoders&quot;">​</a></h2><p>Decoder (<code>src/dendrite/ml/decoders/decoder.py</code>) wraps PyTorch models and classical ML (CSP+LDA/SVM) behind a unified sklearn interface. The registry (<code>src/dendrite/ml/decoders/registry.py</code>) maps decoder type strings to pipeline builders and modality metadata.</p><p><code>DecoderConfig</code> (<code>src/dendrite/ml/decoders/decoder_schemas.py</code>) is the self-describing unit: model type, input shapes, event/label mappings, and per-modality <code>PreprocessingConfig</code> (bandpass, CAR, resampling). Saved with the decoder JSON so inference needs no external config.</p><hr><h2 id="training-infrastructure" tabindex="-1">Training Infrastructure <a class="header-anchor" href="#training-infrastructure" aria-label="Permalink to &quot;Training Infrastructure&quot;">​</a></h2><p><code>TrainingLoop</code> runs in a <code>ProcessPoolExecutor</code> subprocess, isolated from the async event loop. Progress broadcasts to <code>/ws/training</code> via epoch callbacks. Cancellation uses a <code>threading.Event</code> checked between epochs.</p><p>Key cross-module contracts:</p><ul><li>SWA (Stochastic Weight Averaging) skips early-stopping checkpoint restore — the averaged model replaces the best checkpoint</li><li><code>stop_event</code> must be a <code>multiprocessing.Manager().Event()</code> to cross the process boundary</li><li>Loss function (<code>CrossEntropyLoss</code> or <code>FocalLoss</code>) and augmentation strategy are config-driven — see the source for available options</li></ul><p>Source: <code>src/dendrite/ml/training/trainer.py</code></p><hr><h2 id="hyperparameter-search" tabindex="-1">Hyperparameter Search <a class="header-anchor" href="#hyperparameter-search" aria-label="Permalink to &quot;Hyperparameter Search&quot;">​</a></h2><p>Optuna-based search (<code>src/dendrite/ml/search/</code>). Search spaces are auto-generated from Pydantic config <code>hpo</code> field metadata across optimizer, regularization, and augmentation categories. Profiles (<code>Quick</code>/<code>Balanced</code>/<code>Full</code>) scope the number of trials and which categories to search. Early stopping halts search after <code>n_trials / 3</code> consecutive non-improving trials.</p><hr><h2 id="background-optimizer" tabindex="-1">Background Optimizer <a class="header-anchor" href="#background-optimizer" aria-label="Permalink to &quot;Background Optimizer&quot;">​</a></h2><p>Continuous Optuna search during live recording (<code>src/dendrite/ml/search/optuna_runner.py</code>, managed by <code>ml_service.py</code>).</p><p>Runs as an <code>asyncio.Task</code> per mode during live recording. Loads fresh session data from SWMR HDF5, stratified holdout (80/20), one trial per iteration. Searches within the mode&#39;s configured model type (does not switch architectures). Trials beating baseline by <code>promotion_threshold</code> (default 5%) trigger decoder hot-swap via SharedState, with a cooldown between promotions.</p><p>Source: <code>src/dendrite/ml/search/optuna_runner.py</code> (<code>TrialResult</code>, <code>run_optuna_search()</code>)</p><hr><h2 id="evaluation" tabindex="-1">Evaluation <a class="header-anchor" href="#evaluation" aria-label="Permalink to &quot;Evaluation&quot;">​</a></h2><p>Offline decoder evaluation (<code>src/dendrite/ml/evaluation.py</code>) via epoch-based and sliding window methods.</p><h3 id="epoch-evaluation" tabindex="-1">Epoch Evaluation <a class="header-anchor" href="#epoch-evaluation" aria-label="Permalink to &quot;Epoch Evaluation&quot;">​</a></h3><p><code>evaluate_epochs()</code> -- each epoch passed through the decoder and compared to ground truth. Returns accuracy, confusion matrix, and classification report.</p><h3 id="sliding-window-evaluation" tabindex="-1">Sliding Window Evaluation <a class="header-anchor" href="#sliding-window-evaluation" aria-label="Permalink to &quot;Sliding Window Evaluation&quot;">​</a></h3><p><code>evaluate_sliding_window()</code> -- causal sliding window through continuous data, predicting at each step. Instantiates <code>DecisionGate.from_config(config)</code> and passes it to <code>compute_trial_metrics()</code> for metric aggregation — the same function used by online <code>AsynchronousMetrics</code>.</p><p><strong>Decoder window:</strong> Always derived from <code>decoder.input_shapes</code> (e.g., <code>[60, 2000]</code> = 2000 samples = 4.0s at 500Hz). Both offline eval and online async mode use this window size.</p><p><strong>Trial window:</strong> Predictions count toward a trial as soon as the sliding window overlaps the post-onset period — no artificial dead time. Early predictions (where the window mostly contains pre-event data) will be noisy, but the dwell gate handles this naturally by requiring N consecutive predictions of the same class before firing. This gives realistic TTD measurements from event onset rather than from the first full-window prediction.</p><p><strong>Key parameters:</strong></p><ul><li><strong><code>epoch_tmin</code>/<code>epoch_tmax</code></strong> -- trial evaluation boundary. Auto-adjusted if smaller than decoder window. Offline only.</li><li><strong><code>step_ms</code></strong> -- step size between predictions (default 100ms)</li><li><strong><code>code_to_class</code></strong> -- event codes to class indices. Read from decoder&#39;s <code>label_mapping</code>.</li></ul><p><strong>DecisionGate</strong> (<code>src/dendrite/ml/decision_gate.py</code>) controls detection strategy, dwell length, and confidence threshold.</p><p><strong>Optimal gate:</strong> The evaluator grid-searches over strategy, <code>dwell_n</code>, and <code>confidence_threshold</code> combinations to find the gate that maximizes balanced accuracy. The result includes <code>optimal_gate</code> with the best gate config. This uses the same raw per-trial data stored for reaggregation.</p><p><strong>Reaggregation:</strong> The evaluator stores <code>per_trial</code> predictions and <code>background_preds</code>/<code>background_confs</code> in the job result, enabling post-hoc reaggregation with different gate parameters via <code>POST /api/ml/jobs/{job_id}/reaggregate</code> without re-running the decoder.</p><hr><h2 id="models" tabindex="-1">Models <a class="header-anchor" href="#models" aria-label="Permalink to &quot;Models&quot;">​</a></h2><p><code>ModelBase</code> (<code>src/dendrite/ml/models/base.py</code>) defines the abstract interface. Neural models use Pydantic schemas for architecture-specific parameters validated via <code>model_params</code> in <code>DecoderConfig</code>. Available models are listed at <code>/api/ml/models</code>.</p><p>Source: <code>src/dendrite/ml/models/</code></p><hr><p><strong>Related Documentation:</strong></p><ul><li><strong><a href="./processing-layer.html">Processing Layer</a></strong> — Real-time modes and decoder application</li><li><strong><a href="./data-layer.html">Data Layer</a></strong> — Data acquisition and storage</li></ul>',41)])])}const g=a(i,[["render",n]]);export{u as __pageData,g as default};
